import "reflect-metadata";
import { Module, Injectable } from "@nestjs/common";
import { NestFactory } from "@nestjs/core";
async function solve(text: string): Promise<string> { @Module({providers:[{provide:"GREETING",useValue:text}]}) class AppModule {} const app=await NestFactory.createApplicationContext(AppModule,{logger:false}); try { return app.get<string>("GREETING"); } finally { await app.close(); } }

