import { plainToInstance } from "class-transformer";
import { validate, IsString, MinLength } from "class-validator";
class Input { @IsString() @MinLength(2) name!: string; }
async function solve(value: unknown): Promise<boolean> { const dto=plainToInstance(Input,value); const errors=await validate(dto as object,{whitelist:true,forbidNonWhitelisted:true}); return errors.length === 0; }

